GRANT SELECT ON catalog_provider_book,catalog_model_book TO compallm_restricted;
ALTER TABLE catalog_price_book ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalog_read ON catalog_price_book FOR SELECT TO compallm_restricted USING(user_id IS NULL OR(user_id=(SELECT compallm_rls.user_id()) AND organization_id=(SELECT compallm_rls.organization_id())));
CREATE POLICY catalog_write ON catalog_price_book FOR ALL TO compallm_restricted USING(user_id=(SELECT compallm_rls.user_id()) AND organization_id=(SELECT compallm_rls.organization_id())) WITH CHECK(user_id=(SELECT compallm_rls.user_id()) AND organization_id=(SELECT compallm_rls.organization_id()));
GRANT SELECT,INSERT,UPDATE,DELETE ON catalog_price_book TO compallm_restricted;
