ALTER TABLE catalog_price_rate ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalog_read ON catalog_price_rate FOR SELECT TO compallm_restricted USING(EXISTS(SELECT 1 FROM catalog_price_component c JOIN catalog_price_book p ON p.id=c.price_book_id WHERE c.id=catalog_price_rate.component_id));
