CREATE POLICY catalog_write ON catalog_price_parameter FOR ALL TO compallm_restricted USING(EXISTS(SELECT 1 FROM catalog_price_rate r JOIN catalog_price_component c ON c.id=r.component_id JOIN catalog_price_book p ON p.id=c.price_book_id WHERE r.id=catalog_price_parameter.rate_id AND p.user_id=(SELECT compallm_rls.user_id()) AND p.organization_id=(SELECT compallm_rls.organization_id()))) WITH CHECK(EXISTS(SELECT 1 FROM catalog_price_rate r JOIN catalog_price_component c ON c.id=r.component_id JOIN catalog_price_book p ON p.id=c.price_book_id WHERE r.id=catalog_price_parameter.rate_id AND p.user_id=(SELECT compallm_rls.user_id()) AND p.organization_id=(SELECT compallm_rls.organization_id())));
